style:
/* 流彩 —— 蓝紫渐变通栏页眉 + 蓝色模块标题 */

.tw-cosolar--liucai.resume-paper {
  background: #ffffff;
  color: #2b3243;
}

/* 页眉：整条色带铺满纸边，文字反白 */
.tw-cosolar--liucai.resume-paper .paper-header {
  margin: -15mm -15mm 7mm;
  padding: 13mm 15mm 9mm;
  border: none;
  background:
    linear-gradient(118deg, rgba(255, 255, 255, 0.12) 0 16%, rgba(255, 255, 255, 0) 16% 100%),
    linear-gradient(118deg, #2f7fd8 0%, #4f63dd 48%, #7a4ed2 100%);
  color: #ffffff;
  print-color-adjust: exact;
}

.tw-cosolar--liucai.resume-paper .paper-header--photo {
  align-items: center;
  gap: 8mm;
}

.tw-cosolar--liucai.resume-paper .paper-header__main {
  flex: 1 1 auto;
  min-width: 0;
}

.tw-cosolar--liucai.resume-paper .paper-name-row {
  gap: 3mm;
}

.tw-cosolar--liucai.resume-paper .paper-name {
  color: #ffffff;
  font-size: calc(var(--paper-base-size) * 2.3);
  font-weight: 700;
  letter-spacing: 0.04em;
  line-height: 1.25;
}

.tw-cosolar--liucai.resume-paper .paper-identity {
  padding: 0;
  border: none;
  border-radius: 0;
  color: rgba(255, 255, 255, 0.72);
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-cosolar--liucai.resume-paper .paper-role {
  margin-top: 1.6mm;
  color: rgba(255, 255, 255, 0.92);
  font-size: calc(var(--paper-base-size) * 1.04);
  font-weight: 500;
  letter-spacing: 0.02em;
}

.tw-cosolar--liucai.resume-paper .paper-contacts--labeled {
  display: flex;
  flex-wrap: wrap;
  gap: 1.2mm 8mm;
  margin-top: 4.6mm;
  padding: 0;
  border: none;
  color: rgba(255, 255, 255, 0.94);
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-cosolar--liucai.resume-paper .paper-contact {
  display: flex;
  gap: 1.6mm;
  min-width: 0;
}

.tw-cosolar--liucai.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-cosolar--liucai.resume-paper .paper-contact__label {
  flex: 0 0 auto;
  color: rgba(255, 255, 255, 0.62);
}

.tw-cosolar--liucai.resume-paper .paper-photo {
  order: 2;
  width: 24mm;
  height: 32mm;
  border: 1mm solid rgba(255, 255, 255, 0.85);
  border-radius: 50%;
  object-fit: cover;
  box-shadow: none;
  print-color-adjust: exact;
}

/* 模块标题：只有蓝色粗体字，去掉内置的圆圈与细线 */
.tw-cosolar--liucai.resume-paper .paper-style-line .paper-section__title {
  display: block;
  margin: 0 0 2.6mm;
  padding-bottom: 0;
  border-bottom: none;
  color: #2f6ed2;
  font-size: calc(var(--paper-base-size) * 1.16);
  font-weight: 700;
  letter-spacing: 0.04em;
}

.tw-cosolar--liucai.resume-paper .paper-style-line .paper-section__title span::before {
  display: none;
}

.tw-cosolar--liucai.resume-paper .paper-section__icon {
  display: none;
}

/* 条目：标题深色、日期浅灰靠右、专业 / 职位用主题蓝 */
.tw-cosolar--liucai.resume-paper .paper-item-title {
  color: #222a3a;
  font-weight: 700;
}

.tw-cosolar--liucai.resume-paper .paper-item-period {
  color: #6c778c;
  font-size: calc(var(--paper-base-size) * 0.92);
  font-weight: 400;
}

.tw-cosolar--liucai.resume-paper .paper-item-sub {
  color: #3a6fd8;
  font-weight: 600;
}

.tw-cosolar--liucai.resume-paper .paper-item-sub span + span::before {
  content: " | ";
  margin-right: 0;
  color: #c2cbdb;
}

.tw-cosolar--liucai.resume-paper .paper-item-tag {
  color: #3a6fd8;
}

/* 求职意向：一行流，标签浅、值深 */
.tw-cosolar--liucai.resume-paper .is-job_intention .paper-item {
  display: flex;
  flex-wrap: wrap;
  gap: 1.4mm 8mm;
}

.tw-cosolar--liucai.resume-paper .is-job_intention .paper-item-head {
  display: flex;
  flex: 0 0 auto;
  gap: 8mm;
  justify-content: flex-start;
}

.tw-cosolar--liucai.resume-paper .is-job_intention .paper-item-title::before {
  content: "意向岗位：";
  color: #7a879c;
  font-weight: 400;
}

.tw-cosolar--liucai.resume-paper .is-job_intention .paper-item-period::before {
  content: "意向城市：";
  color: #7a879c;
  font-weight: 400;
}

.tw-cosolar--liucai.resume-paper .is-job_intention .paper-item-sub {
  flex: 0 0 auto;
  display: flex;
  flex-wrap: wrap;
  gap: 1.2mm 8mm;
  margin-top: 0;
  color: #3a4155;
  font-weight: 400;
}

.tw-cosolar--liucai.resume-paper .is-job_intention .paper-item-sub span + span::before {
  content: "·";
  margin-right: 6mm;
  color: #c2cbdb;
}

/* 正文细节 */
.tw-cosolar--liucai.resume-paper .paper-note {
  color: #5d687b;
}

.tw-cosolar--liucai.resume-paper .paper-note__tag {
  padding: 0;
  border: none;
  border-radius: 0;
  background: transparent;
  color: #2f6ed2;
  font-weight: 600;
}

.tw-cosolar--liucai.resume-paper .paper-meta-line {
  color: #6c778c;
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-cosolar--liucai.resume-paper .paper-rich {
  color: #39445a;
}

.tw-cosolar--liucai.resume-paper .paper-rich li {
  margin: 0.5mm 0;
}

.tw-cosolar--liucai.resume-paper .paper-rich ul {
  padding-left: 1.1em;
}

.tw-cosolar--liucai.resume-paper .paper-rich li::marker {
  color: #3a6fd8;
}

.tw-cosolar--liucai.resume-paper .paper-skill {
  border-bottom: 1px solid #e8eef7;
}

.tw-cosolar--liucai.resume-paper .paper-skill__name {
  color: #2b3243;
  font-weight: 600;
}

.tw-cosolar--liucai.resume-paper .paper-skill__dots {
  display: none;
}

.tw-cosolar--liucai.resume-paper .paper-skill__level {
  display: inline;
  color: #6c778c;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-cosolar--liucai.resume-paper .paper-footer {
  margin-top: 8mm;
  padding-top: 2.4mm;
  border-top: 1px solid #e6ecf5;
  color: #9aa5b8;
}

@media print {
  .tw-cosolar--liucai.resume-paper .paper-header {
    print-color-adjust: exact;
  }
}
